---- LOOK AND FEEL ----
-----------------------

-- Border colours are owned by the quickshell theme switcher: on every theme change
-- it writes theme-borders.conf and runs `hyprctl keyword` for the live update.
-- Reading that file back here is what makes a theme survive `hyprctl reload` --
-- without it the hardcoded fallbacks below silently win and the borders snap back
-- to cyan/green. Fallbacks are used only when the file doesn't exist yet.
local function themeBorders()
    local active   = { colors = { "rgba(33ccffee)", "rgba(00ff99ee)" }, angle = 45 }
    local inactive = "rgba(595959aa)"

    local f = io.open("@hyprState@/theme-borders.conf", "r")
    if not f then return active, inactive end

    for line in f:lines() do
        local a = line:match("col%.active_border%s*=%s*(.+)")
        if a then
            local cols = {}
            for c in a:gmatch("rgba?%b()") do cols[#cols + 1] = c end
            if #cols > 0 then
                active = { colors = cols, angle = tonumber(a:match("(%d+)%s*deg")) or 45 }
            end
        end

        local i = line:match("col%.inactive_border%s*=%s*(rgba?%b())")
        if i then inactive = i end
    end
    f:close()

    return active, inactive
end

local activeBorder, inactiveBorder = themeBorders()

-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 20,

        border_size = 2,

        col = {
            active_border   = activeBorder,
            inactive_border = inactiveBorder,
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        -- Dim unfocused windows here rather than inside each app. A terminal
        -- doing its own fading (kitty's inactive_text_alpha) only dims glyphs,
        -- not background cells, which seams anything drawing a coloured block
        -- with glyph end-caps — tmux status pills, powerline prompts. The
        -- compositor dims the whole surface, so the two stay in step.
        -- 0.15 is roughly what kitty's 0.85 text alpha used to look like.
        dim_inactive = true,
        dim_strength = 0.15,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
            enabled   = true,
            size      = 3,
            passes    = 3,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Default curves and animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
--
-- `speed` is a DURATION in ds (1ds = 100ms), so a smaller number is a faster
-- animation. Rather than hand-tuning seventeen values, scale them all with one
-- knob: 1.0 is the stock config, 0.5 runs everything at double speed.
local animSpeed = 0.5

local function anim(spec)
    if spec.speed then
        spec.speed = spec.speed * animSpeed
    end
    hl.animation(spec)
end

hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })

-- niri's two easing curves, written as the standard cubic-bezier
-- approximations of the Penner easings it names by string.
hl.curve("niriOutExpo",    { type = "bezier", points = { {0.19, 1},    {0.22, 1}    } })
hl.curve("niriOutQuad",    { type = "bezier", points = { {0.25, 0.46}, {0.45, 0.94} } })

-- Springs, ported from niri's defaults. Hyprland parameterises a spring by
-- absolute damping and niri by damping RATIO, so crossing over means
--
--     dampening = 2 * zeta * sqrt(stiffness * mass)      -- mass = 1 here
--
-- niri's defaults, and what they land on:
--     window-movement / -resize / overview   zeta 1.0, k  800 -> 56.568542
--     workspace-switch                       zeta 1.0, k 1000 -> 63.245553
--     config-notification-open-close         zeta 0.6, k 1000 -> 37.947332
--
-- zeta 1.0 is critically damped -- no overshoot at all. What was here before
-- was
--     stiffness = 71.2633 / animSpeed^2,  dampening = 15.8273644 / animSpeed
-- which works out to zeta 0.9374 (a slight bounce) at k 285, so niri's springs
-- are both tighter and about 1.7x quicker. Those numbers are kept here in case
-- the bounce is ever wanted back.
--
-- Note these are deliberately NOT divided by animSpeed the way the old spring
-- was. They are niri's values as it ships them, not a curve tuned against this
-- config's speed knob. The consequence: animSpeed no longer reaches the
-- springs. It still scales every duration below, but these three stay put. To
-- bring them back under the knob, divide stiffness by animSpeed^2 and dampening
-- by animSpeed, which is what the old spring did and why it squared.
hl.curve("niriMove",   { type = "spring", mass = 1, stiffness = 800,  dampening = 56.568542 })
hl.curve("niriWs",     { type = "spring", mass = 1, stiffness = 1000, dampening = 63.245553 })
hl.curve("niriNotify", { type = "spring", mass = 1, stiffness = 1000, dampening = 37.947332 })

anim({ leaf = "global",        enabled = true,  speed = 10,   bezier = "default" })
anim({ leaf = "border",        enabled = true,  speed = 5.39, bezier = "easeOutQuint" })
-- <- niri window-movement / window-resize. `speed` is inert on a spring leaf --
-- Hyprland takes the pace from stiffness -- so the number here does nothing and
-- is left at its old value rather than invented.
anim({ leaf = "windows",       enabled = true,  speed = 4.79, spring = "niriMove" })
-- <- niri window-open: 150 ms ease-out-expo. 1.5 * animSpeed 0.5 = 75 ms.
-- niri has no popin equivalent, so the style is dropped; add
-- `style = "popin 87%"` back if the scale-up is wanted with niri's curve.
anim({ leaf = "windowsIn",     enabled = true,  speed = 1.5,  bezier = "niriOutExpo" })
-- <- niri window-close: 150 ms ease-out-quad, likewise 75 ms after scaling.
anim({ leaf = "windowsOut",    enabled = true,  speed = 1.5,  bezier = "niriOutQuad" })
anim({ leaf = "fadeIn",        enabled = true,  speed = 1.73, bezier = "almostLinear" })
anim({ leaf = "fadeOut",       enabled = true,  speed = 1.46, bezier = "almostLinear" })
anim({ leaf = "fade",          enabled = true,  speed = 3.03, bezier = "quick" })
-- <- niri config-notification-open-close (zeta 0.6, the one bouncy default).
anim({ leaf = "layers",        enabled = true,  speed = 3.81, spring = "niriNotify" })
anim({ leaf = "layersIn",      enabled = true,  speed = 4,    bezier = "easeOutQuint", style = "fade" })
anim({ leaf = "layersOut",     enabled = true,  speed = 1.5,  bezier = "linear",       style = "fade" })
anim({ leaf = "fadeLayersIn",  enabled = true,  speed = 1.79, bezier = "almostLinear" })
anim({ leaf = "fadeLayersOut", enabled = true,  speed = 1.39, bezier = "almostLinear" })
-- <- niri workspace-switch (zeta 1.0, k 1000).
anim({ leaf = "workspaces",    enabled = true,  speed = 1.94, spring = "niriWs",       style = "fade" })
anim({ leaf = "workspacesIn",  enabled = true,  speed = 1.21, bezier = "almostLinear", style = "fade" })
anim({ leaf = "workspacesOut", enabled = true,  speed = 1.94, bezier = "almostLinear", style = "fade" })
-- <- niri overview-open-close (same spring as window movement).
anim({ leaf = "zoomFactor",    enabled = true,  speed = 7,    spring = "niriMove" })

-- Ref https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/
-- "Smart gaps" / "No gaps when only"
-- uncomment all if you wish to use that.
-- hl.workspace_rule({ workspace = "w[tv1]", gaps_out = 0, gaps_in = 0 })
-- hl.workspace_rule({ workspace = "f[1]",   gaps_out = 0, gaps_in = 0 })
