-- Pin workspaces to monitors. Without these rules Hyprland hands workspace N to
-- monitor ID N-1, and the IDs come from DRM connector enumeration order rather
-- than the order the monitors are declared -- on the desktop DP-1 enumerates as
-- ID 0, so it would claim workspace 1 despite the left screen being primary.
--
-- The output names come from hosts/<hostname>.lua, loaded at the top. A machine
-- with one display names no secondary, and everything lands on the primary --
-- better than the old behaviour, which pinned 6-10 to a DP-1 that did not exist
-- on the laptop and stranded them.
local primary   = hostCfg.primary
local secondary = hostCfg.secondary or primary

local vscodeWorkspace = 2
local youtubeWorkspace = 10

if primary then
    for i = 1, 5 do
        if i ~= vscodeWorkspace then -- defined on its own below, with the monocle layout
            hl.workspace_rule({ workspace = tostring(i), monitor = primary, default = (i == 1) })
        end
    end

    for i = 6, 10 do
        hl.workspace_rule({
            workspace  = tostring(i),
            monitor    = secondary,
            default    = (i == 6),
            persistent = (i == youtubeWorkspace), -- keep it alive so the rule below always lands
        })
    end

    -- The VSCode workspace. `persistent` keeps it alive while empty so the rules
    -- below always have somewhere to land.
    hl.workspace_rule({
        workspace  = tostring(vscodeWorkspace),
        monitor    = primary,
        layout     = "monocle",
        persistent = true,
    })
end

-- Layouts picked through the Quickshell layout switcher (SUPER+SHIFT+space),
-- which rewrites this file on every choice. It loads here, after the rules
-- above, so a chosen layout wins over them -- workspace_rule merges field by
-- field, so the monitor / default / persistent settings above survive being
-- overridden this way, and only `layout` changes.
--
-- pcall because the file does not exist until a layout has been chosen, and a
-- missing module is a raised error rather than a nil return. Delete the file to
-- go back to the defaults above.
-- Same as monitors above: written by quickshell's layout switcher, absent
-- until first use.
pcall(dofile, "@hyprState@/workspace-layouts.lua")

-- Send every VSCode window to that workspace. `silent` means opening a new one
-- (or a new project window) does not drag focus off whatever you are on.
hl.window_rule({
    name      = "vscode-to-monocle-workspace",
    match     = { class = "^code$" },
    workspace = tostring(vscodeWorkspace) .. " silent",
})

-- Same treatment for the YouTube PWA. Chrome app windows take their class from
-- the shortcut id rather than the .desktop StartupWMClass, so this matches
-- chrome-<app-id>-<profile> and not crx_<app-id>.
hl.window_rule({
    name      = "youtube-to-media-workspace",
    match     = { class = "^chrome-agimnkijcaahngcdmfeangaknmldooml-Profile_2$" },
    workspace = tostring(youtubeWorkspace) .. " silent",
})

-- The scratchpad crowd: apps you dip into and dismiss rather than work in, so
-- they live on the special workspace SUPER+S toggles instead of taking a tile
-- on whatever you were doing. Floating, because a special workspace tiles like
-- any other and a single window would otherwise fill the screen.
--
-- No `silent` here, unlike the two rules above: those assign windows that open
-- by themselves and must not steal focus, while these you launch on purpose, so
-- the scratchpad slides open with the window you just asked for. Add `silent`
-- if you would rather they stash themselves quietly.
--
-- Both classes are what the windows actually report on wayland, not what their
-- .desktop advertises -- 1Password's StartupWMClass says "1Password" and the
-- window says "1password". Add another app by widening the alternation, after
-- checking it with `hyprctl clients -j`.
hl.window_rule({
    name      = "scratchpad-apps",
    match     = { class = "^(1password|org\\.signal\\.Signal)$" },

    workspace = "special:magic",
    float     = true,
})

-- Replace the password manager with a black rectangle in anything that captures
-- the screen. Same class as the scratchpad rule above; widen the alternation to
-- `^(1password|org\\.signal\\.Signal)$` to cover Signal too.
--
-- THE FIELD NAME IS LOAD-BEARING. It is `no_screen_share`, snake_case. The
-- Hyprland wiki documents this rule as `noscreenshare`, which is the old conf
-- syntax and is **silently ignored** under the lua parser -- and rule fields are
-- not validated at all (`hl.window_rule{ __bogus__ = 1 }` is accepted without a
-- word), so the wrong spelling is not an error you would ever see. It is a
-- privacy rule that quietly does nothing, failing toward leaking rather than
-- toward a visible glitch. Same trap as `hyprctl keyword` under this parser.
-- Upstream knows the wiki is wrong: hyprwm/Hyprland discussion #12417.
--
-- Measured on 0.56.0 rather than assumed, by capturing a region with grim --
-- which goes through wlr-screencopy, the same path a screencast takes -- and
-- counting non-black pixels: 100% visible with `noscreenshare`, 0.2% with
-- `no_screen_share`, and back to 100% once the rule was disabled.
--
-- This blocks the whole screencopy path, so your own `grim` screenshots get the
-- black rectangle as well. niri's equivalent takes a mode ("screencast" vs
-- "screen-capture") and can block casts while still allowing screenshots;
-- Hyprland's is a boolean and cannot.
hl.window_rule({
    name  = "blackout-password-manager",
    match = { class = "^(1password)$" },

    no_screen_share = true,
})

-- See https://wiki.hypr.land/Configuring/Layouts/Dwindle-Layout/ for more
hl.config({
    dwindle = {
        preserve_split = true, -- You probably want this
    },
})

-- See https://wiki.hypr.land/Configuring/Layouts/Master-Layout/ for more
hl.config({
    master = {
        new_status = "master",
    },
})

-- See https://wiki.hypr.land/Configuring/Layouts/Scrolling-Layout/ for more
hl.config({
    scrolling = {
        fullscreen_on_one_column = true,

        -- 1 (Hyprland's default) scrolls the camera the LEAST amount that
        -- makes the focused column fully visible, and 0 centers the focused
        -- column on every focus change. This config wants 1 plus an exception:
        -- see centerIfCrowded further down, which centers by hand in the one
        -- case that reads badly under the fit behaviour -- a focused column
        -- pinned to an edge beside a neighbour too wide to share the screen
        -- with it. Centering has to be that exception rather than the rule the
        -- option applies, which is what 0 would make it.
        --
        -- Read the history before changing this back. 0 was tried first, to get
        -- niri's `center-focused-column = "on-overflow"`, and it does not mean
        -- what it looks like. It means "always center", and the conditional
        -- half comes from the camera, which centers the whole tape when the
        -- tape fits:
        --
        --     // if the content fits in viewport, center it
        --     if (maxExtent < usablePrimary)
        --         m_offset = std::round((maxExtent - usablePrimary) / 2.0);
        --     -- ScrollTapeController.cpp:222-224, v0.55.4
        --
        -- `<` is strict, and with the stock 0.5 width two columns are EXACTLY
        -- as wide as the screen, so the test is false and a two-terminal
        -- workspace centered the focused terminal with the other one hanging
        -- half off the edge:
        --
        --     x= -352 w=739 right= 387   <- half off the left edge
        --     x=  401 w=739 right=1140   <- focused, centered
        --
        -- centerCol lives at ScrollingAlgorithm.cpp:403-413 and fitCol beside
        -- it. Neither is reachable from a dispatcher: `center` is the only
        -- layout message that touches the camera alone, every `fit` mode
        -- resizes columns, and `move <px>` scrolls but then focuses whatever
        -- lands in the middle. Focus is the camera control here.
        focus_fit_method = 1,

        -- The widths are a preference now, not a mechanism. They were chosen
        -- while focus_fit_method was 0, to keep every combination that fits
        -- strictly UNDER the monitor width, since at equality the camera stops
        -- centering the tape. Under 1 that only decides whether a tape which
        -- fits sits centered with a small margin (0.49: x=37..761 and
        -- 775..1499 on a 1536 px monitor) or edge to edge (0.5). Kept for the
        -- margin. 0.667 is spelled 0.66 for the same reason: 0.333 * 1536 +
        -- 0.667 * 1536 = 1536.0000000000002, which is over, not equal.
        column_width           = 0.49,
        explicit_column_widths = "0.333, 0.49, 0.66, 1.0",
    },
})

