hl.config({
    misc = {
        force_default_wallpaper = -1,    -- Set to 0 or 1 to disable the anime mascot wallpapers
        disable_hyprland_logo   = false, -- If true disables the random hyprland logo / anime girl background. :(

        -- Honour xdg-activation requests instead of only marking the window
        -- urgent. This is what makes the "View" button on a notification
        -- actually jump to the window: quickshell invokes the action over
        -- D-Bus, the app asks to be raised, and with this off Hyprland denies
        -- the raise and sets the urgent hint -- which is the workspace blink.
        --
        -- The tradeoff is that any app can now pull focus this way, not just
        -- ones you asked to. Opt individual offenders back out with
        --   hl.windowrule("suppressevent activatefocus", "class:^(foo)$")
        focus_on_activate = true,
    },
})


-------------------
---- XWAYLAND -----
-------------------

-- X11 has no per-output scale, so XWayland clients always render at scale 1 and
-- get resampled to the monitor's 1.67. The only real fix is running the app
-- natively on Wayland; this just picks the least ugly resampling for the ones
-- that cannot.
--
-- The default filter is nearest neighbour, which at a fractional factor
-- duplicates pixels unevenly: glyph stems come out 1px wide in some places and
-- 2px in others, and the grey antialiasing fringes the app drew get replicated
-- as hard blocks. Text reads as jagged and un-antialiased. Bilinear resampling
-- blurs slightly instead, which is what KWin does unconditionally -- no
-- resolution is recovered either way, it just stops looking broken.
hl.config({
    xwayland = {
        use_nearest_neighbor = false,
    },
})


