local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
-- Session menu: lock, suspend, log out, restart, shut down. This used to end the
-- session outright on a single keypress -- SUPER+M sits one key from SUPER+N and
-- there was nothing between the typo and every unsaved buffer. The menu opens on
-- Lock, and the three destructive entries need a second press to commit.
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("qs ipc call session toggle"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
-- Fullscreen, and maximize on the shifted key. Two binds because they are two
-- different things: "fullscreen" hands the window the whole output and tells the
-- client it is fullscreen, "maximized" only grows it to fill the tiling area, so
-- the gaps, the bar and any layer surface stay where they are. The
-- suppress-maximize-events rule further down does not get in the way of either
-- -- it drops maximize requests coming *from* applications, not the dispatcher.
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind(mainMod .. " + tab", hl.dsp.exec_cmd(switchWindow))
-- SUPER+D and SUPER+R both open the launcher. R is the old rofi binding kept for
-- muscle memory; drop it if you never reach for it.
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(menu))
-- Audio output/input picker. The network panel opens from its bar pill instead;
-- this one has no bar entry yet, so it needs a key.
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("qs ipc call audio toggle"))
-- Theme switcher overlay. SHIFT because plain SUPER+T is togglesplit above.
hl.bind(mainMod .. " + SHIFT + T", hl.dsp.exec_cmd("qs ipc call theme toggle"))
-- Wallpaper picker overlay.
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("qs ipc call wallpaper toggle"))
-- Clipboard history. SHIFT because plain SUPER+V is the float toggle above, and
-- SUPER+SHIFT+V is what the cliphist docs use anyway.
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("qs ipc call clipboard toggle"))
-- The browser picker, with no link to open -- pick a browser and a profile and
-- it starts empty. This is the one thing SUPER+D cannot do: the launcher offers
-- "Google Chrome", because a chrome profile is not a desktop entry and nothing
-- in the desktop database knows the three of them exist.
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("qs ipc call browser toggle"))
-- Tiled layout picker for the focused workspace. It applies the choice with
-- `hyprctl eval` and writes it to workspace-layouts.lua, which is required back
-- in above -- so the choice survives a reload and a login. SHIFT+space rather
-- than a letter: every mnemonic one (L, T, S) is already
-- focus/move/togglesplit/special.
hl.bind(mainMod .. " + SHIFT + space", hl.dsp.exec_cmd("qs ipc call layout toggle"))

-- The function row, for a keyboard with none of the XF86 media keys -- which is
-- most desktop keyboards, including this one. The layout is a ThinkPad's, key
-- for key: mute, volume, mic mute, brightness. That is a row a lot of hands
-- already know, and it needs none of the mnemonic letters, which ran out years
-- ago.
--
-- These duplicate the XF86 binds further down rather than replacing them: both
-- exist because either keyboard may be the one plugged in.
--
-- Volume goes straight to wpctl, while brightness goes through the shell. Not
-- an inconsistency: the OSD watches PipeWire directly, so it shows itself
-- whoever changed the volume, and wpctl needs nothing running. DDC has no such
-- channel -- BrightnessService is the only thing that can reach an external
-- monitor, and the only thing that knows what the level now is.
hl.bind(mainMod .. " + F1", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"))
-- -l 1 caps the raise at 100%: without it wpctl will happily amplify past unity
-- and distort, which is a strange thing for a volume key to do.
hl.bind(mainMod .. " + F2", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { repeating = true })
hl.bind(mainMod .. " + F3", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { repeating = true })
hl.bind(mainMod .. " + F4", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"))
-- `repeating` so holding one sweeps: the service coalesces the writes.
hl.bind(mainMod .. " + F5", hl.dsp.exec_cmd("qs ipc call brightness down"), { repeating = true })
hl.bind(mainMod .. " + F6", hl.dsp.exec_cmd("qs ipc call brightness up"),   { repeating = true })
-- F7 carries the row past where a ThinkPad stops: displays are the same kind of
-- thing as the six above it. The settings panel (monitor layout, and the shell
-- settings the compositor knows nothing about) is the only panel here with
-- neither a keybind nor a bar pill, so `qs ipc call settings toggle` was the
-- entire way in.
hl.bind(mainMod .. " + F7", hl.dsp.exec_cmd("qs ipc call settings toggle"))

-- Jump to whatever window is asking for attention, else back to the one you came
-- from. This is Hyprland's focusurgentorlast, rebuilt: the Lua dispatcher table
-- has no urgent variant (hl.dsp exposes focus/window/workspace/group and nothing
-- else), but hl.get_urgent_window and hl.get_last_window are both there, so the
-- pieces just need assembling. focus{window=} switches workspace on its own when
-- the target lives elsewhere, which is the entire point of the bind.
--
-- Mostly a fallback since misc.focus_on_activate went on above: apps that request
-- activation properly now raise themselves when you click a notification action.
-- The ones that only set the urgent hint -- XWayland clients going through
-- _NET_ACTIVE_WINDOW, or apps that fire the action and then do nothing -- still
-- leave you with a blinking workspace pill and no way to get there.
local function focusUrgentOrLast()
    local target = hl.get_urgent_window() or hl.get_last_window()
    if target then hl.dispatch(hl.dsp.focus({ window = target })) end
end

hl.bind(mainMod .. " + U", focusUrgentOrLast)

-- Every layout message below is rejected outright by the algorithms that do not
-- implement it -- "Unknown dwindle layoutmsg: cyclenext", "no such layoutmsg for
-- scrolling" -- so anything layout-specific has to ask the workspace what it is
-- running first. hl.get_active_workspace().tiled_layout is that answer; the four
-- values it can take are the four algorithms compiled into Hyprland.

-- SUPER+T restructures the tiling under the active window, in whichever sense
-- its layout has one. This was `layout("togglesplit")` flat, which only dwindle
-- accepts -- on the other three it errored on every press:
--
--     layout     togglesplit   orientationnext   consume_or_expel
--     dwindle    ok            error             error
--     master     error         ok                error
--     monocle    error         error             error
--     scrolling  error         error             ok
--
-- Monocle has no entry because it has nothing to restructure: one window fills
-- the workspace and the rest are behind it. The key is a no-op there, which is
-- the honest result and quieter than an error in the log.
--
-- (Moved out of the app binds up top so it sits with the rest of the
-- layout-aware code. It lives on T rather than J because J is focus-down.)
local restructure = {
    dwindle   = "togglesplit",
    master    = "orientationnext",
    -- Folds the window into the neighbouring column, or gives it its own if it
    -- is already alone. Warns "no adjacent column" on the last column of the
    -- tape, where there is nothing to fold into -- use SUPER+O to expel there.
    scrolling = "consume_or_expel next",
}

hl.bind(mainMod .. " + T", function()
    local ws = hl.get_active_workspace()
    if not ws then return end

    local msg = restructure[ws.tiled_layout]
    if msg then hl.dispatch(hl.dsp.layout(msg)) end
end)

-- Cycle the window stack. Directional focus is useless on a monocle workspace
-- (every window occupies the same box), so these are how you move through it.
--
-- No single dispatcher cycles on every layout, and the generic candidates fail
-- *silently* -- they return "ok" and do nothing -- so this needs a branch:
--
--     layout     cycle_next()   cycle_next{tiled=true}   layout("cycle*")
--     dwindle    works          works                    error: Unknown
--     master     works          works                    works both ways
--     monocle    no-op          forward only             works both ways
--     scrolling  --             --                       error: no such layoutmsg
--
-- cycle_next has no reverse in any spelling. prev / previous / reverse / last /
-- backwards as table keys are all accepted and silently ignored, and every
-- positional form -- cycle_next("prev"), cycle_next({"prev","tiled"}) -- is a
-- no-op. Only the layout messages walk backwards.
-- Center the focused column when it and the column beyond it cannot share the
-- screen.
--
-- Hyprland scrolls the camera the least amount that makes the newly focused
-- column fully visible, which pins it against whichever edge it entered from.
-- That is fine while two columns fit together -- you get the one you came from
-- and the one you are on -- and it reads badly when they do not, because the
-- focused column sits against an edge beside a sliver of a neighbour that was
-- never going to fit. Measured on a 719 px column next to a 1278 px one, on a
-- 1536 px monitor:
--
--     pinned:    x=  27 right= 746   margins left  27, right 790
--     centered:  x= 408 right=1128   margins left 408, right 408
--
-- So: plain focus, then center in that case only. `center` is the one layout
-- message that moves the camera and nothing else -- every `fit` mode resizes
-- columns instead of scrolling, and `move <px>` scrolls but then focuses
-- whatever lands in the middle (ScrollingAlgorithm.cpp:1445-1452, v0.55.4).
--
-- The neighbour is found by reading the workspace geometry, NOT by focusing it.
-- A version that focused one column further and came back was built first and
-- dropped after a live comparison: focusing a column necessarily scrolls the
-- camera onto it, so that version also changed which neighbour you see on every
-- ordinary move -- the column ahead rather than the one you came from. That is
-- a different feature, and it is in this file's history rather than in it.
--
-- Two things this deliberately does not do. It never centers at the end of the
-- tape, where no neighbour failed to fit. And it leaves the vertical directions
-- alone: a column's windows are stacked inside it, so there is no second column
-- to make room for.

-- The layout works in logical pixels and monitor.width is physical, so the
-- scale divides. There is no reserved area in the Lua monitor object, which is
-- why this is a width rather than a usable width: the bar reserves 32 px at the
-- top and nothing at the sides, so horizontally the two agree. A bar on the
-- left or right would make this over-estimate.
local function monitorWidth()
    local m = hl.get_active_monitor()
    if not m or not m.width or not m.scale or m.scale == 0 then return nil end
    return m.width / m.scale
end

-- Windows sharing an x are one column, and a column is as wide as its widest
-- window. Rebuilt on each call rather than tracked, because a column has no
-- identity in the Lua API -- only windows do.
local function columnsOf(ws)
    local byX = {}
    for _, w in ipairs(ws:get_windows()) do
        if not w.floating then
            local x = w.at.x
            if byX[x] then
                if w.size.x > byX[x].width then byX[x].width = w.size.x end
            else
                byX[x] = { x = x, width = w.size.x }
            end
        end
    end

    local list = {}
    for _, c in pairs(byX) do list[#list + 1] = c end
    table.sort(list, function(a, b) return a.x < b.x end)
    return list
end

-- Can the two sit on screen together? The gap is taken from the two boxes
-- rather than from gaps_in, so it stays correct whatever the gaps are set to.
-- Both columns carry the same camera offset, so the difference between them
-- holds even mid-animation.
local function fitsBeside(target, neighbour, width)
    if not neighbour then return false end

    local gap
    if neighbour.x < target.at.x then
        gap = target.at.x - (neighbour.x + neighbour.width)
    else
        gap = neighbour.x - (target.at.x + target.size.x)
    end

    return target.size.x + neighbour.width + gap <= width
end

-- The focused column, its index among the columns, the columns either side, and
-- the monitor width -- everything both rules below need. nil when the workspace
-- is not scrolling, or when nothing is focused: `move +col` on the last column
-- scrolls to the end and focuses nothing (ScrollingAlgorithm.cpp:1397-1403), so
-- that is a real case rather than defensive padding.
local function focusedColumn()
    local ws = hl.get_active_workspace()
    if not ws or ws.tiled_layout ~= "scrolling" then return nil end

    local target = hl.get_active_window()
    if not target then return nil end

    local width = monitorWidth()
    if not width then return nil end

    local cols = columnsOf(ws)
    for i, c in ipairs(cols) do
        if c.x == target.at.x then
            return { target = target, width = width, cols = cols, idx = i,
                     left = cols[i - 1], right = cols[i + 1] }
        end
    end

    return nil
end

local function centerIfCrowded(dir)
    local f = focusedColumn()
    if not f then return end

    local neighbour = (dir == "left") and f.left or f.right
    if not neighbour then return end

    if not fitsBeside(f.target, neighbour, f.width) then
        hl.dispatch(hl.dsp.layout("center"))
    end
end

-- Directional focus, with the centering rule on the two horizontal directions.
local function focusColumn(dir)
    return function()
        hl.dispatch(hl.dsp.focus({ direction = dir }))
        if dir == "left" or dir == "right" then centerIfCrowded(dir) end
    end
end

local function cycleStack(dir)
    return function()
        local ws = hl.get_active_workspace()
        if not ws then return end

        -- Scrolling has no cycle message, but focus l/r walks the columns and
        -- wraps at both ends of the tape (scrolling:wrap_focus, on by default),
        -- which is the same thing and a real inverse -- no walk-forward needed.
        if ws.tiled_layout == "scrolling" then
            hl.dispatch(hl.dsp.layout(dir == "prev" and "focus l" or "focus r"))
            -- Survives the wrap without a special case: walking off the left
            -- end lands on the rightmost column, and the neighbour that matters
            -- there is still the one to its left.
            centerIfCrowded(dir == "prev" and "left" or "right")
            return
        end

        -- Master and monocle both take cyclenext/cycleprev. Preferred over the
        -- generic dispatcher for master too: it is one dispatch each way rather
        -- than the n-1 the reverse below costs.
        if ws.tiled_layout == "monocle" or ws.tiled_layout == "master" then
            hl.dispatch(hl.dsp.layout(dir == "prev" and "cycleprev" or "cyclenext"))
            return
        end

        local step = hl.dsp.window.cycle_next({ tiled = true })
        if dir ~= "prev" then
            hl.dispatch(step)
            return
        end

        -- That leaves dwindle, which has no reverse, so walk the ring forward until we land
        -- one short of where we started. Driving that with the same dispatcher
        -- makes it an exact inverse by construction, with no assumption about the
        -- order Hyprland cycles in. It runs inside a single callback, so no
        -- intermediate focus is ever composited.
        local tiled = 0
        for _, w in ipairs(ws:get_windows()) do
            if not w.floating then tiled = tiled + 1 end
        end
        for _ = 2, tiled do hl.dispatch(step) end
    end
end

hl.bind(mainMod .. " + bracketright", cycleStack("next"))
hl.bind(mainMod .. " + bracketleft",  cycleStack("prev"))

-- Column controls for the scrolling layout. The tape is wider than the monitor
-- by design, so it needs keys the other three layouts have no use for: move the
-- viewport along it, move a column within it, and set how wide a column is.
--
-- Gated on the layout rather than bound flat. Every message here is rejected by
-- dwindle/master/monocle, and a flat bind would mean four keys that log an error
-- on every press outside a scrolling workspace.
local function scrollingMsg(msg)
    return function()
        local ws = hl.get_active_workspace()
        if not ws or ws.tiled_layout ~= "scrolling" then return end
        hl.dispatch(hl.dsp.layout(msg))
    end
end

-- Move focus one column each way, carrying the camera with it.
--
-- This comment used to say the two keys scrolled the viewport and left focus
-- where it was. They do not: `move -col` focuses the previous column and warps
-- the cursor into it (ScrollingAlgorithm.cpp:1414-1439), and a measurement
-- shows the focused window's address changing on every press. They differ from
-- SUPER+H/L only in being column-wise rather than spatial, and in the warp.
local function scrollColumn(msg, dir)
    return function()
        local ws = hl.get_active_workspace()
        if not ws or ws.tiled_layout ~= "scrolling" then return end

        hl.dispatch(hl.dsp.layout(msg))
        centerIfCrowded(dir)
    end
end

hl.bind(mainMod .. " + comma",  scrollColumn("move -col", "left"))
hl.bind(mainMod .. " + period", scrollColumn("move +col", "right"))

-- Move the focused column along the tape. Wraps at both ends by default
-- (scrolling:wrap_swapcol), so a column can be sent from one end to the other.
hl.bind(mainMod .. " + SHIFT + comma",  scrollingMsg("swapcol l"))
hl.bind(mainMod .. " + SHIFT + period", scrollingMsg("swapcol r"))

-- Resizing moves the same question as focusing does: after the width changes,
-- can a neighbour still sit beside this column?
--
-- Hyprland re-fits the column itself after every colresize -- centerOrFit runs
-- in colresize's own scope guard (ScrollingAlgorithm.cpp:1475-1481) -- but a fit
-- only CLAMPS. A column that is already fully visible does not move, so a column
-- centered by the rule above stays centered after it shrinks back to a width
-- where a neighbour would fit. Growing has the mirror problem: the column stays
-- pinned to an edge beside a neighbour it can no longer share the screen with.
--
-- So: grow past the point where either neighbour fits, and the column centers.
-- Shrink back, and it un-centers. The un-centering is a focus round trip, since
-- focus is the only camera control -- focusing the neighbour scrolls it into
-- view, and returning by window does not move the camera, because the column is
-- visible by then. Where the layout is already right, both dispatches are
-- no-ops: the neighbour is fully visible, so nothing scrolls.
--
-- The neighbour is picked by how much of it is already on screen, so the camera
-- moves the shorter way and a column with a fitting neighbour on each side does
-- not jump across the tape.
local function recenterAfterResize()
    local f = focusedColumn()
    if not f then return end

    local leftFits  = fitsBeside(f.target, f.left,  f.width)
    local rightFits = fitsBeside(f.target, f.right, f.width)

    if not leftFits and not rightFits then
        hl.dispatch(hl.dsp.layout("center"))
        return
    end

    local m = hl.get_active_monitor()
    if not m then return end

    local screenL, screenR = m.x, m.x + f.width
    local function onScreen(c)
        if not c then return -1 end
        return math.max(0, math.min(c.x + c.width, screenR) - math.max(c.x, screenL))
    end

    local dir
    if leftFits and rightFits then
        dir = (onScreen(f.left) >= onScreen(f.right)) and "left" or "right"
    elseif leftFits then
        dir = "left"
    else
        dir = "right"
    end

    hl.dispatch(hl.dsp.focus({ direction = dir }))
    hl.dispatch(hl.dsp.focus({ window = f.target }))
end

local function resizeColumn(msg)
    return function()
        local ws = hl.get_active_workspace()
        if not ws or ws.tiled_layout ~= "scrolling" then return end

        hl.dispatch(hl.dsp.layout(msg))
        recenterAfterResize()
    end
end

-- Column width. The steps are fractions of the monitor, matching
-- scrolling:column_width; +conf cycles the preset widths in
-- scrolling:explicit_column_widths, which is usually the one you want. That
-- list is set above and is NOT the stock one: every preset there is chosen so
-- that a set of columns which fits stays strictly under the monitor width,
-- which is what makes focus_fit_method = 0 center on overflow only. Read the
-- comment beside column_width before changing a number here.
hl.bind(mainMod .. " + minus",         resizeColumn("colresize -0.1"))
hl.bind(mainMod .. " + equal",         resizeColumn("colresize +0.1"))
hl.bind(mainMod .. " + SHIFT + equal", resizeColumn("colresize +conf"))

-- Grow the focused column into whatever space is left on the monitor, and pull
-- a column that has scrolled half off back into view.
hl.bind(mainMod .. " + G",         scrollingMsg("fit expand"))
hl.bind(mainMod .. " + SHIFT + G", scrollingMsg("fit_into_view"))

-- Stack windows into one column and pull them back out again. SUPER+T does both
-- in one key (see restructure above); these are the explicit halves, and the
-- only way out of the last column on the tape, where SUPER+T has no neighbour
-- to fold into.
--
-- There is also a `promote` message, left unbound: it does exactly what expel
-- does -- new column immediately right of the one the window left, rest of the
-- stack closing up -- in every position tried, top, middle and bottom of a
-- stack, first and last column. The only difference is on a window that is
-- already alone in its column, where expel warns "column has only one window"
-- and promote returns ok. Both no-op.
hl.bind(mainMod .. " + I", scrollingMsg("consume"))
hl.bind(mainMod .. " + O", scrollingMsg("expel"))

-- Move focus with mainMod + arrow keys. focusColumn rather than the dispatcher
-- straight: on a scrolling workspace the horizontal two carry the centering
-- rule.
hl.bind(mainMod .. " + left",  focusColumn("left"))
hl.bind(mainMod .. " + right", focusColumn("right"))
hl.bind(mainMod .. " + up",    focusColumn("up"))
hl.bind(mainMod .. " + down",  focusColumn("down"))

-- Same thing, vim-style. Note these do nothing on the monocle workspace, where
-- every window occupies the same box -- use the bracket binds above there.
hl.bind(mainMod .. " + H", focusColumn("left"))
hl.bind(mainMod .. " + J", focusColumn("down"))
hl.bind(mainMod .. " + K", focusColumn("up"))
hl.bind(mainMod .. " + L", focusColumn("right"))

-- Move the active window in a direction. Same monocle caveat as above: with
-- every window in the same box there is nowhere to move it to.
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "down" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "right" }))

-- Cross monitors explicitly. The plain directional binds above already fall off
-- the edge onto the next monitor -- that is binds:window_direction_monitor_fallback,
-- on by default -- but only when there is no window that way on the current one.
-- On the scrolling layout the tape extends past both screen edges, so there is
-- almost always another column to move to first and the fallback never fires.
-- These do not care what is on screen.
hl.bind(mainMod .. " + CTRL + H", hl.dsp.focus({ monitor = "l" }))
hl.bind(mainMod .. " + CTRL + L", hl.dsp.focus({ monitor = "r" }))

-- Throw the active window at the other monitor. Focus follows it.
hl.bind(mainMod .. " + CTRL + SHIFT + H", hl.dsp.window.move({ monitor = "l" }))
hl.bind(mainMod .. " + CTRL + SHIFT + L", hl.dsp.window.move({ monitor = "r" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
-- Brightness through the shell rather than straight to brightnessctl. Two
-- reasons. It is the only way to reach an external monitor at all -- those have
-- no kernel backlight device, so their brightness lives in the monitor firmware
-- and is written over DDC/CI, which BrightnessService does. And bare
-- `brightnessctl set` is actively wrong on a machine with no backlight class:
-- it falls through to the first device of any class it finds, which here is
-- `input1::numlock`, so these two binds used to toggle the numlock LED.
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("qs ipc call brightness up"),                       { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("qs ipc call brightness down"),                     { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


---------------------
---- SCREENSHOTS ----
---------------------

-- grim captures, slurp picks the region, wl-copy puts it on the clipboard.
-- `tee` also drops a timestamped copy in ~/Pictures/Screenshots, so a shot is
-- not lost the moment something else overwrites the clipboard.
--
-- The region bind guards on slurp's exit status: pressing Escape to cancel makes
-- slurp exit non-zero, and without the guard grim would be handed an empty
-- geometry and tee would leave a 0-byte file behind.
local shotDir  = [["$HOME/Pictures/Screenshots"]]
local shotFile = [["$HOME/Pictures/Screenshots/$(date +%Y-%m-%d_%H-%M-%S).png"]]

local function shot(grimArgs, guard)
    return hl.dsp.exec_cmd(
        "mkdir -p " .. shotDir .. "; " .. (guard or "") ..
        "grim " .. grimArgs .. " - | tee " .. shotFile .. " | wl-copy"
    )
end

-- Print               -> drag out a region
-- SHIFT + Print       -> the whole monitor you are currently on
-- SUPER + Print       -> just the focused window
hl.bind("Print",                  shot([[-g "$g"]], [[g=$(slurp) || exit 0; ]]))
hl.bind("SHIFT + Print",          shot([[-o "$(hyprctl -j activeworkspace | jq -r .monitor)"]]))
hl.bind(mainMod .. " + Print",    shot([[-g "$(hyprctl -j activewindow | jq -r '"\(.at[0]),\(.at[1]) \(.size[0])x\(.size[1])"')"]]))


