-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- The bar draws its background, and optionally its pills, at less than full
-- alpha so the wallpaper reads through. Layer surfaces are not blurred by
-- default -- only windows are -- so without this the bar is a clear window onto
-- whatever is behind it, and the text sitting on it is only as readable as the
-- wallpaper allows. Everything quickshell puts on screen shares the one
-- namespace, so this covers the panels and popups too; they are opaque, so for
-- them it is a no-op.
--
-- ignore_alpha leaves fully transparent pixels alone, which is what makes a 0%
-- strip with translucent pills blur behind the pills only, rather than frosting
-- a band across the top of the screen.
--
-- On/off is the settings panel's, in quickshell/bar.conf beside the two alphas
-- it belongs with. The panel applies it live with `hyprctl eval`; reading it
-- back here is what survives a reload, exactly like theme-borders.conf above.
local function barBlur()
    -- quickshell's state, moved there by spec 2. This read still pointed at the
    -- old ~/.config path, which spec 2 emptied.
    local f = io.open("@quickshellState@/bar.conf", "r")
    if not f then return true end

    local blur = true
    for line in f:lines() do
        local v = line:match("^blur%s*=%s*(%d+)")
        if v then blur = tonumber(v) ~= 0 end
    end
    f:close()

    return blur
end

hl.layer_rule({
    name         = "blur-quickshell",
    match        = { namespace = "^quickshell$" },
    blur         = barBlur(),
    ignore_alpha = 0.05,
})

